import React from "react";
import { useState } from "react";
import { addIngredientTagToDatabase } from "../hooks/handleDatabase"; // データベース操作用の関数をインポート
import Creatable from "react-select/creatable"; // 新しい選択肢を作成可能なセレクトコンポーネント
import { Button, TextField } from "@mui/material"; // Material-UIのコンポーネント
import "./AddIngredients.css"; // スタイルシートのインポート

// AddIngredientsコンポーネント
const AddIngredients = ({
  ingredients, // 現在の材料一覧（配列）
  setIngredients, // 材料一覧を更新するための関数
  ingredientTags, // 既存の材料タグ（配列）
  update, // 更新フラグ（再レンダリング用）
  setUpdate, // 更新フラグを変更する関数
  forSeatchTags, // 検索用の材料タグ（配列）
  setForSeatchTags, // 検索用材料タグを更新する関数
}) => {
  // 分量のステート
  const [quantityVal, setQuantityVal] = useState("");

  // 現在選択されている材料タグ（新規作成も含む）
  const [selectedOption, setSelectedOption] = useState(null);

  // セレクトバー用にingredientTags（配列）をオブジェクトの配列に変換
  const newOptions = [];
  ingredientTags.map((tag) => newOptions.push({ value: tag, label: tag }));

  // セレクトバーで選択された値を処理する関数
  const handleChange = (selectedOption) => {
    setSelectedOption(selectedOption); // 選択されたオプションをステートに保存
    console.log(`Option selected:`, selectedOption.value); // デバッグ用ログ
  };

  // 新しい材料タグをデータベースに追加し、ステートを更新する関数
  const createIngredientTag = () => {
    addIngredientTagToDatabase(selectedOption.value); // データベースにタグを追加
    setUpdate(!update); // 更新フラグを反転させて再レンダリングをトリガー
  };

  // 材料と分量を結合して材料一覧に追加する関数
  const addIngredient = () => {
    // 新しい材料を追加し、重複を排除
    setIngredients([
      ...new Set([...ingredients, selectedOption.value + ": " + quantityVal]),
    ]);

    // 検索用タグに追加し、重複を排除
    setForSeatchTags([...new Set([...forSeatchTags, selectedOption.value])]);

    // 新規材料タグの場合はデータベースに追加
    ingredientTags.every(
      (ingredientTag) => ingredientTag !== selectedOption.value
    ) && createIngredientTag();

    // 次の材料登録のためにステートを初期化
    setQuantityVal("");
  };

  // Creatableコンポーネントのカスタマイズスタイル
  const customStyles2 = {
    control: (provided, state) => ({
      ...provided,
      width: "100%",
      borderRadius: "none",
      border: "1px solid gray",
      backgroundColor: "#FFFFFF",
      textAlign: "center",
      "&:hover": {
        border: "2px solid red",
        cursor: "pointer",
      },
    }),
  };

  // コンポーネントのレンダリング
  return (
    <div className="add-ingredients">
      <h3>検索に用いる材料を検索して必要な分量を入力してください</h3>
      <div className="add-ingredients-form">
        <div className="add-ingredients-form-left">
          {/* 材料を検索・選択するセレクトバー */}
          <Creatable
            options={newOptions} // セレクトバーの選択肢
            value={selectedOption} // 現在選択されているオプション
            placeholder="材料を検索してください" // プレースホルダー
            onChange={handleChange} // 選択変更時の処理
            styles={customStyles2} // カスタムスタイル
          />
          {/* 分量を入力するテキストフィールド */}
          <TextField
            value={quantityVal} // 現在の分量
            placeholder="分量" // プレースホルダー
            variant="standard" // テキストフィールドのスタイル
            onChange={(e) => setQuantityVal(e.target.value)} // 入力変更時の処理
          />
        </div>
        <div className="add-ingredients-form-right">
          {/* 材料を追加するボタン */}
          <Button variant="contained" onClick={addIngredient}>
            材料を追加
          </Button>
        </div>
      </div>
    </div>
  );
};

export default AddIngredients;
